### guided_diffusion/condition_methods.py  (core of GML-DPS & PSLD)

from abc import ABC, abstractmethod
import torch

__CONDITIONING_METHOD__ = {}

def register_conditioning_method(name: str):
    def wrapper(cls):
        if __CONDITIONING_METHOD__.get(name, None):
            raise NameError(f"Name {name} is already registered!")
        __CONDITIONING_METHOD__[name] = cls
        return cls
    return wrapper


def get_conditioning_method(name: str, operator, noiser, **kwargs):
    if __CONDITIONING_METHOD__.get(name, None) is None:
        raise NameError(f"Name {name} is not defined!")
    return __CONDITIONING_METHOD__[name](operator=operator, noiser=noiser, **kwargs)

class ConditioningMethod(ABC):
    """Abstract base implementing latent-space conditioning.

    Goodness  ∇  is built in  grad_and_value();
    Gluing  term is added in PosteriorSamplingPlus.
    """
    def __init__(self, operator, noiser, **kwargs):
        self.operator = operator      # A  in the paper
        self.noiser   = noiser        #  n  in the paper    
    # ─────────────────────────────────────────────────────────────
    #   helper blocks
    # ─────────────────────────────────────────────────────────────
    def project(self, data, noisy_measurement, **kwargs):
        """Orthogonal projection implementing ‘gluing’ for linear A."""
        return self.operator.project(data=data, measurement=noisy_measurement, **kwargs)

    def grad_and_value(self, x_prev, x_0_hat, measurement, **kwargs):
        """Goodness gradient  ∇g  (Eq. (7) in the paper).

        For Gaussian   g = ‖y-Ax̂₀‖₂ ;  for Poisson   g = ‖(y-Ax̂₀)/y‖.
        """
        if self.noiser.__name__ == 'gaussian':
            difference = measurement - self.operator.forward(x_0_hat, **kwargs)
            norm       = torch.linalg.norm(difference)
            norm_grad  = torch.autograd.grad(outputs=norm, inputs=x_prev)[0]
        elif self.noiser.__name__ == 'poisson':
            Ax         = self.operator.forward(x_0_hat, **kwargs)
            difference = measurement - Ax
            norm       = (torch.linalg.norm(difference) / measurement.abs()).mean()
            norm_grad  = torch.autograd.grad(outputs=norm, inputs=x_prev)[0]
        else:
            raise NotImplementedError
        return norm_grad, norm

    @abstractmethod
    def conditioning(self, x_t, measurement, noisy_measurement=None, **kwargs):
        pass

# ─────────────────────────────────────────────────────────────────
#   GML-DPS   (goodness only)
# ─────────────────────────────────────────────────────────────────
@register_conditioning_method(name='ps')
class PosteriorSampling(ConditioningMethod):
    def __init__(self, operator, noiser, **kwargs):
        super().__init__(operator, noiser)
        self.scale = kwargs.get('scale', 1.0)   #  γ  in Alg.-1

    def conditioning(self, x_prev, x_t, x_0_hat, measurement, **kwargs):
        norm_grad, norm = self.grad_and_value(x_prev=x_prev,
                                              x_0_hat=x_0_hat,
                                              measurement=measurement,
                                              **kwargs)
        # modified reverse SDE step (Eq. (9))
        x_t -= self.scale * norm_grad
        return x_t, norm

# ─────────────────────────────────────────────────────────────────
#   PSLD   (goodness + gluing; provably stable)
# ─────────────────────────────────────────────────────────────────
@register_conditioning_method(name='ps+')
class PosteriorSamplingPlus(ConditioningMethod):
    def __init__(self, operator, noiser, **kwargs):
        super().__init__(operator, noiser)
        self.num_sampling = kwargs.get('num_sampling', 5)  # K  in Alg.-2
        self.scale        = kwargs.get('scale', 1.0)      #  γ  shared

    def conditioning(self, x_prev, x_t, x_0_hat, measurement, noisy_measurement=None, **kwargs):
        # Goodness term (same as GML-DPS but Monte-Carlo averaged)
        norm = 0
        for _ in range(self.num_sampling):
            x_0_hat_noise = x_0_hat + 0.05 * torch.randn_like(x_0_hat)
            difference    = measurement - self.operator.forward(x_0_hat_noise)
            norm         += torch.linalg.norm(difference) / self.num_sampling
        norm_grad = torch.autograd.grad(outputs=norm, inputs=x_prev)[0]
        x_t -= self.scale * norm_grad
        # Gluing term: orthogonal projection using A† (Eq. (10))
        if noisy_measurement is not None:
            x_t = self.project(data=x_t, noisy_measurement=noisy_measurement, **kwargs)
        return x_t, norm

# ─────────────────────────────────────────────────────────────────
#   Pure projection (baseline) & identity for ablation
# ─────────────────────────────────────────────────────────────────
@register_conditioning_method(name='vanilla')
class Identity(ConditioningMethod):
    def conditioning(self, x_t):
        return x_t

@register_conditioning_method(name='projection')
class Projection(ConditioningMethod):
    def conditioning(self, x_t, noisy_measurement, **kwargs):
        return self.project(data=x_t, noisy_measurement=noisy_measurement, **kwargs)
